import type { Rules, RuleViolation } from '@beer-die/core';
import { sql } from 'drizzle-orm';
import {
  type AnyPgColumn,
  boolean,
  check,
  customType,
  foreignKey,
  index,
  integer,
  jsonb,
  pgTable,
  pgView,
  text,
  timestamp,
  unique,
  uuid,
} from 'drizzle-orm/pg-core';

const citext = customType<{ data: string }>({ dataType: () => 'citext' });

// Every timestamp is timestamptz in UTC, and its value always comes from the injected Clock.
const ts = (name: string) => timestamp(name, { withTimezone: true, mode: 'date' });

// UUIDv7, generated by Postgres 18.
const id = () =>
  uuid('id')
    .primaryKey()
    .default(sql`uuidv7()`);

export const users = pgTable('users', {
  id: id(),
  // Null once the account is deleted.
  email: citext('email').unique(),
  createdAt: ts('created_at').notNull(),
  deletedAt: ts('deleted_at'),
});

// One live code per email: requesting a new code overwrites the row, which invalidates the
// earlier code. Only an HMAC of the code is stored.
export const authCodes = pgTable(
  'auth_codes',
  {
    id: id(),
    email: text('email').notNull().unique(),
    codeHmac: text('code_hmac').notNull(),
    createdAt: ts('created_at').notNull(),
    expiresAt: ts('expires_at').notNull(),
    attempts: integer('attempts').notNull().default(0),
    consumedAt: ts('consumed_at'),
  },
  (t) => [check('auth_codes_attempts_nonnegative', sql`${t.attempts} >= 0`)],
);

export const sessions = pgTable(
  'sessions',
  {
    id: id(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id),
    // Only the SHA-256 of the token is stored.
    tokenSha256: text('token_sha256').notNull().unique(),
    client: text('client', { enum: ['web', 'native'] }).notNull(),
    createdAt: ts('created_at').notNull(),
    lastUsedAt: ts('last_used_at').notNull(),
    // 30 days after last use.
    expiresAt: ts('expires_at').notNull(),
  },
  (t) => [
    index('sessions_user_id_idx').on(t.userId),
    check('sessions_client_valid', sql`${t.client} in ('web', 'native')`),
  ],
);

// `key` is `email:<hmac>` or `ip:<hmac>`, so neither raw value is stored.
export const rateLimits = pgTable('rate_limits', {
  key: text('key').primaryKey(),
  windowStart: ts('window_start').notNull(),
  count: integer('count').notNull(),
});

// Drained by the worker. `params` never holds stats or plaintext secrets (a sign-in code is
// sealed with a key derived from AUTH_SECRET), and it is wiped once the row is terminal.
export const emailOutbox = pgTable(
  'email_outbox',
  {
    id: id(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id),
    template: text('template').notNull(),
    params: jsonb('params').notNull().default({}),
    attempts: integer('attempts').notNull().default(0),
    nextAttemptAt: ts('next_attempt_at').notNull(),
    sentAt: ts('sent_at'),
    lastError: text('last_error'),
    createdAt: ts('created_at').notNull(),
  },
  // The worker claims sign-in codes and other mail separately (see drainOutbox), each in
  // send order from its own index. Rows past the attempt cap are out of both, so dropped and
  // failed mail doesn't slow every claim. 'sign_in_code' is SIGN_IN_CODE in
  // mail/templates.ts and 5 is MAX_SEND_ATTEMPTS in mail/outbox.ts.
  (t) => [
    index('email_outbox_pending_codes_idx')
      .on(t.nextAttemptAt)
      .where(sql`${t.sentAt} is null and ${t.attempts} < 5 and ${t.template} = 'sign_in_code'`),
    index('email_outbox_pending_mail_idx')
      .on(t.nextAttemptAt)
      .where(sql`${t.sentAt} is null and ${t.attempts} < 5 and ${t.template} <> 'sign_in_code'`),
  ],
);

// Rules and settings are edited in place (audited, slice 4); each game snapshots the rules at
// its first submission, so editing them never re-validates existing games.
export const leagues = pgTable(
  'leagues',
  {
    id: id(),
    name: text('name').notNull(),
    targetScore: integer('target_score').notNull().default(11),
    winBy: integer('win_by').notNull().default(2),
    sinkPoints: integer('sink_points').notNull().default(0),
    sinkEndsGame: boolean('sink_ends_game').notNull().default(false),
    confirmationWindowDays: integer('confirmation_window_days').notNull().default(7),
    exhibitionCorrectionWindowDays: integer('exhibition_correction_window_days')
      .notNull()
      .default(30),
    createdAt: ts('created_at').notNull(),
  },
  (t) => [
    check('leagues_target_score_min', sql`${t.targetScore} >= 1`),
    check('leagues_win_by_min', sql`${t.winBy} >= 1`),
    check('leagues_sink_points_min', sql`${t.sinkPoints} >= 0`),
    check(
      'leagues_confirmation_window_days_range',
      sql`${t.confirmationWindowDays} between 1 and 30`,
    ),
    check(
      'leagues_exhibition_correction_window_days_range',
      sql`${t.exhibitionCorrectionWindowDays} between 0 and 365`,
    ),
  ],
);

// The per-league identity. Games will reference memberships, not users, so deleting an
// account can anonymize a player without rewriting game history. `name_key` (NFKC +
// lowercase, derived by the server) keeps display names unique within a league, and a
// name stays reserved for as long as its row exists.
export const memberships = pgTable(
  'memberships',
  {
    id: id(),
    leagueId: uuid('league_id')
      .notNull()
      .references(() => leagues.id),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id),
    displayName: text('display_name').notNull(),
    nameKey: text('name_key').notNull(),
    role: text('role', { enum: ['member', 'commissioner'] }).notNull(),
    status: text('status', {
      enum: ['pending', 'approved', 'removed', 'left', 'deleted'],
    }).notNull(),
    emailNotifications: boolean('email_notifications').notNull().default(true),
    createdAt: ts('created_at').notNull(),
  },
  (t) => [
    unique('memberships_league_name_key_unique').on(t.leagueId, t.nameKey),
    unique('memberships_league_user_unique').on(t.leagueId, t.userId),
    index('memberships_user_id_idx').on(t.userId),
    check('memberships_role_valid', sql`${t.role} in ('member', 'commissioner')`),
    check(
      'memberships_status_valid',
      sql`${t.status} in ('pending', 'approved', 'removed', 'left', 'deleted')`,
    ),
  ],
);

// The league's log of commissioner actions, visible to every member. Append-only: triggers
// (migration 0004) refuse UPDATE, DELETE, and TRUNCATE, even for the table's owner. Only a
// superuser can switch them off, so the production app role (delivery slice 8) must be
// neither, and lack those grants too. `details` never holds names, emails, or tokens, so
// deleting an account never needs to rewrite it.
export const auditEvents = pgTable(
  'audit_events',
  {
    id: id(),
    leagueId: uuid('league_id')
      .notNull()
      .references(() => leagues.id),
    actorMembershipId: uuid('actor_membership_id')
      .notNull()
      .references(() => memberships.id),
    action: text('action').notNull(),
    targetType: text('target_type').notNull(),
    targetId: uuid('target_id').notNull(),
    actorWasParticipant: boolean('actor_was_participant').notNull(),
    details: jsonb('details').notNull(),
    createdAt: ts('created_at').notNull(),
  },
  // The log is read newest first, paging on the (time-ordered) UUIDv7 id.
  (t) => [index('audit_events_league_id_id_idx').on(t.leagueId, t.id)],
);

// A shareable join link. Only the SHA-256 of its token is stored; the link is shown once.
export const invites = pgTable(
  'invites',
  {
    id: id(),
    leagueId: uuid('league_id')
      .notNull()
      .references(() => leagues.id),
    tokenSha256: text('token_sha256').notNull().unique(),
    createdBy: uuid('created_by')
      .notNull()
      .references(() => memberships.id),
    createdAt: ts('created_at').notNull(),
    expiresAt: ts('expires_at').notNull(),
    revokedAt: ts('revoked_at'),
  },
  (t) => [index('invites_league_id_idx').on(t.leagueId)],
);

// A recorded game. Its rules snapshot is the league rules at first submission, and every
// revision is checked against it, so editing the league rules never re-validates a game.
// Retrying a submission with the same idempotency key returns this game, provided the
// payload hash matches. Season columns (season_id, team ids) arrive with seasons.
export const games = pgTable(
  'games',
  {
    id: id(),
    leagueId: uuid('league_id')
      .notNull()
      .references(() => leagues.id),
    kind: text('kind', { enum: ['season', 'exhibition'] }).notNull(),
    status: text('status', { enum: ['pending', 'confirmed', 'expired', 'voided'] }).notNull(),
    openRevisionId: uuid('open_revision_id').references((): AnyPgColumn => gameRevisions.id),
    // The revision stats read. Set only by settleRevision (domain/games.ts).
    confirmedRevisionId: uuid('confirmed_revision_id').references(
      (): AnyPgColumn => gameRevisions.id,
    ),
    // When the game first counted, also set only by settleRevision. A reopened revision that
    // confirms keeps it, so an exhibition game's correction window never restarts.
    confirmedAt: ts('confirmed_at'),
    // Set at first submission (or when a confirmed game is reopened); corrections keep it.
    windowExpiresAt: ts('window_expires_at'),
    rulesSnapshot: jsonb('rules_snapshot').$type<Rules>().notNull(),
    submittedBy: uuid('submitted_by')
      .notNull()
      .references(() => memberships.id),
    idempotencyKey: uuid('idempotency_key').notNull(),
    payloadSha256: text('payload_sha256').notNull(),
    createdAt: ts('created_at').notNull(),
  },
  (t) => [
    unique('games_idempotency_unique').on(t.leagueId, t.submittedBy, t.idempotencyKey),
    check('games_kind_valid', sql`${t.kind} in ('season', 'exhibition')`),
    check('games_status_valid', sql`${t.status} in ('pending', 'confirmed', 'expired', 'voided')`),
    // A game that has counted keeps counting through a reopen that expires or is voided.
    check(
      'games_confirmed_has_revision',
      sql`(${t.status} = 'confirmed') = (${t.confirmedRevisionId} is not null)`,
    ),
    check(
      'games_confirmed_has_time',
      sql`(${t.confirmedRevisionId} is not null) = (${t.confirmedAt} is not null)`,
    ),
  ],
);

// Immutable: a correction creates a new revision rather than editing one.
export const gameRevisions = pgTable(
  'game_revisions',
  {
    id: id(),
    gameId: uuid('game_id')
      .notNull()
      .references((): AnyPgColumn => games.id),
    number: integer('number').notNull(),
    status: text('status', {
      enum: ['open', 'confirmed', 'superseded', 'expired', 'voided', 'rejected'],
    }).notNull(),
    createdBy: uuid('created_by')
      .notNull()
      .references(() => memberships.id),
    playedAt: ts('played_at').notNull(),
    winner: text('winner', { enum: ['A', 'B'] }).notNull(),
    // checkRules against the game's rules snapshot; empty means the revision conforms.
    ruleViolations: jsonb('rule_violations').$type<RuleViolation[]>().notNull(),
    overrideStatus: text('override_status', { enum: ['requested', 'approved', 'rejected'] }),
    createdAt: ts('created_at').notNull(),
  },
  (t) => [
    unique('game_revisions_game_number_unique').on(t.gameId, t.number),
    check('game_revisions_number_min', sql`${t.number} >= 1`),
    check(
      'game_revisions_status_valid',
      sql`${t.status} in ('open', 'confirmed', 'superseded', 'expired', 'voided', 'rejected')`,
    ),
    check('game_revisions_winner_valid', sql`${t.winner} in ('A', 'B')`),
    check(
      'game_revisions_override_status_valid',
      sql`${t.overrideStatus} in ('requested', 'approved', 'rejected')`,
    ),
  ],
);

// Exactly four rows per revision, two per side. `is_sub` is derived by the server.
export const revisionPlayers = pgTable(
  'revision_players',
  {
    id: id(),
    revisionId: uuid('revision_id')
      .notNull()
      .references(() => gameRevisions.id),
    side: text('side', { enum: ['A', 'B'] }).notNull(),
    membershipId: uuid('membership_id')
      .notNull()
      .references(() => memberships.id),
    isSub: boolean('is_sub').notNull(),
    points: integer('points').notNull(),
    sinks: integer('sinks').notNull(),
  },
  (t) => [
    unique('revision_players_revision_membership_unique').on(t.revisionId, t.membershipId),
    check('revision_players_side_valid', sql`${t.side} in ('A', 'B')`),
    check('revision_players_points_range', sql`${t.points} between 0 and 99`),
    check('revision_players_sinks_range', sql`${t.sinks} between 0 and 99`),
  ],
);

// A player's confirmation of one revision; a new revision starts with none of the old ones.
// The foreign key to revision_players means only that revision's players can confirm it.
export const confirmations = pgTable(
  'confirmations',
  {
    id: id(),
    revisionId: uuid('revision_id').notNull(),
    membershipId: uuid('membership_id').notNull(),
    kind: text('kind', { enum: ['player', 'forced'] }).notNull(),
    createdAt: ts('created_at').notNull(),
  },
  (t) => [
    unique('confirmations_revision_membership_unique').on(t.revisionId, t.membershipId),
    foreignKey({
      name: 'confirmations_revision_player_fk',
      columns: [t.revisionId, t.membershipId],
      foreignColumns: [revisionPlayers.revisionId, revisionPlayers.membershipId],
    }),
    check('confirmations_kind_valid', sql`${t.kind} in ('player', 'forced')`),
  ],
);

// Stats read only this view (SPEC §3.3): one row per player per counted game, from the game's
// confirmed revision and nothing else, so a game counts only once all four players (and, for a
// rule-breaking result, a commissioner) have signed off. There are no stored counters to drift.
// The partner is the other player on the same side of that revision, the one who actually
// played; each side has exactly two players. Season, team, and opponent columns arrive with
// the slices that read them.
export const countedResults = pgView('counted_results', {
  leagueId: uuid('league_id').notNull(),
  gameId: uuid('game_id').notNull(),
  kind: text('kind', { enum: ['season', 'exhibition'] }).notNull(),
  revisionId: uuid('revision_id').notNull(),
  playedAt: ts('played_at').notNull(),
  membershipId: uuid('membership_id').notNull(),
  side: text('side', { enum: ['A', 'B'] }).notNull(),
  partnerMembershipId: uuid('partner_membership_id').notNull(),
  isSub: boolean('is_sub').notNull(),
  won: boolean('won').notNull(),
  points: integer('points').notNull(),
  sinks: integer('sinks').notNull(),
}).as(sql`
  select g.league_id, g.id as game_id, g.kind, r.id as revision_id, r.played_at,
         p.membership_id, p.side, q.membership_id as partner_membership_id, p.is_sub,
         p.side = r.winner as won, p.points, p.sinks
  from games g
  join game_revisions r on r.id = g.confirmed_revision_id and r.game_id = g.id
  join revision_players p on p.revision_id = r.id
  join revision_players q
    on q.revision_id = r.id and q.side = p.side and q.membership_id <> p.membership_id
`);
